{
  "categoryId": "{{catId}}",
  "listingType": "SELL",
  "version": 1,
  "isActive": true,
  "title": {
    "en": "List Poultry",
    "hi": "मुर्गी पालन सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "poultryCategory",
      "type": "DROPDOWN",
      "label": {
        "en": "Poultry Category",
        "hi": "कुक्कुट श्रेणी"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "poultry__poultry_category",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "poultryName",
      "type": "DROPDOWN",
      "label": {
        "en": "Poultry / Bird",
        "hi": "कुक्कुट / पक्षी"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 20,
      "optionSetKey": "poultry__poultry_name",
      "parentField": "poultryCategory",
      "editableOnUpdate": false,
      "visibleWhen": {
        "field": "poultryCategory",
        "operator": "notEquals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "poultryNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify Poultry Name",
        "hi": "कृपया कुक्कुट का नाम बताएं"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "poultryCategory",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "description",
      "type": "TEXTAREA",
      "label": {
        "en": "Description",
        "hi": "विवरण"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "fieldLength": 1000,
      "inlineEditable": true,
      "validation": {
        "maxLength": 1000
      }
    },
    {
      "fieldKey": "purpose",
      "type": "DROPDOWN",
      "label": {
        "en": "Purpose",
        "hi": "उद्देश्य"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 50,
      "optionSetKey": "poultry__purpose"
    },
    {
      "fieldKey": "age",
      "type": "NUMBER",
      "label": {
        "en": "Age",
        "hi": "आयु"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 60,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "ageUnit",
      "type": "DROPDOWN",
      "label": {
        "en": "Age Unit",
        "hi": "आयु इकाई"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 70,
      "optionSetKey": "poultry__age_unit"
    },
    {
      "fieldKey": "avgWeight",
