      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 90,
      "optionSetKey": "poultry__health",
      "multiple": true
    },
    {
      "fieldKey": "availableQty",
