        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 130,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 140,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "(actualPrice - offeredPrice) / actualPrice * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 150,
      "common": true
    },
    {
      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 160,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "contactNumber",
      "type": "TEXT",
      "label": {
        "en": "Contact Number",
        "hi": "संपर्क नंबर"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": true,
      "displayOrder": 170,
      "common": true,
      "fieldLength": 10,
      "validation": {
        "regex": "^[6-9][0-9]{9}$",
        "maxLength": 10
      }
    },
    {
      "fieldKey": "showContact",
      "type": "BOOLEAN",
      "label": {
        "en": "Show my contact number & address to buyers",
        "hi": "मेरा संपर्क नंबर और पता खरीदारों को दिखाएं"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": false,
      "displayOrder": 180,
      "help": {
        "en": "If off, your number and full address stay hidden — buyers must send a contact request that you approve before they are revealed.",
        "hi": "यदि बंद है, तो आपका नंबर और पूरा पता छिपा रहेगा — खरीदार संपर्क अनुरोध भेजेंगे और आपकी स्वीकृति के बाद ही ये दिखेंगे।"
      },
      "common": true
    }
  ]
}

